(function(){function setStatus(button,message){var status=button.parentElement?button.parentElement.querySelector('.copy-status'):null;if(status)status.textContent=message;}
document.querySelectorAll('[data-copy-text]').forEach(function(button){button.addEventListener('click',function(){var text=button.getAttribute('data-copy-text')||'';function fallbackCopy(){var textarea=document.createElement('textarea');textarea.value=text;textarea.setAttribute('readonly','');textarea.style.position='fixed';textarea.style.top='-999px';document.body.appendChild(textarea);textarea.select();try{document.execCommand('copy');setStatus(button,'Copied.');}catch(err){setStatus(button,'Copy unavailable in this browser.');}
document.body.removeChild(textarea);}
if(!navigator.clipboard||!navigator.clipboard.writeText){fallbackCopy();return;}
navigator.clipboard.writeText(text).then(function(){setStatus(button,'Copied.');}).catch(fallbackCopy);});});document.querySelectorAll('.accordion__header').forEach(function(header){header.setAttribute('aria-expanded','false');var body=header.nextElementSibling;if(body){if(!body.id)body.id='acc-body-'+Math.random().toString(36).slice(2,8);header.setAttribute('aria-controls',body.id);}
header.addEventListener('click',function(){window.setTimeout(function(){var item=header.closest('.accordion__item');var expanded=item&&item.classList.contains('active');header.setAttribute('aria-expanded',expanded?'true':'false');},0);});});document.querySelectorAll('[data-open-goal]').forEach(function(link){link.addEventListener('click',function(){var id=link.getAttribute('data-open-goal');var item=id?document.getElementById(id):null;var header=item?item.querySelector('.accordion__header'):null;if(!item||!header)return;window.setTimeout(function(){if(!item.classList.contains('active'))header.click();item.scrollIntoView({behavior:'smooth',block:'start'});},80);});});})();